#include <cstdio>
#include <cuda_runtime.h>
int main(){int v; const char* names[]={"PageableMemoryAccess","PageableMemoryAccessUsesHostPageTables","HostNativeAtomicSupported","Integrated","CanMapHostMemory","ConcurrentManagedAccess","DirectManagedMemAccessFromHost","HostRegisterSupported","HostRegisterReadOnlySupported"}; cudaDeviceAttr a[]={cudaDevAttrPageableMemoryAccess,cudaDevAttrPageableMemoryAccessUsesHostPageTables,cudaDevAttrHostNativeAtomicSupported,cudaDevAttrIntegrated,cudaDevAttrCanMapHostMemory,cudaDevAttrConcurrentManagedAccess,cudaDevAttrDirectManagedMemAccessFromHost,cudaDevAttrHostRegisterSupported,cudaDevAttrHostRegisterReadOnlySupported}; for(int i=0;i<9;i++){cudaDeviceGetAttribute(&v,a[i],0);printf("%s=%d\n",names[i],v);} int rt,dv; cudaRuntimeGetVersion(&rt); cudaDriverGetVersion(&dv); printf("runtime=%d driver=%d\n",rt,dv); return 0;}
